    #include <iostream>
#include <vector>
#include <queue>
using namespace std;

int kthSmallest(int n, int m, int k) {
	priority_queue<int> pq;

	// check all combinations
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++) {

		    // if size of heap is less 
		    // than k.
			if (pq.size() < k) {
				pq.push(i*j);
			}

			// else if current value is 
			// less than heap top.
			else if (i*j < pq.top()) {
				pq.pop();
				pq.push(i*j);
			}
		}
	}

	return pq.top();
}

